import { createMemoryAdapter, createRouter } from "@canonical/router-core";
import { RouterProvider } from "@canonical/router-react";
import { fireEvent, render, screen } from "@testing-library/react";
import type { ReactElement } from "react";
import { describe, expect, it, vi } from "vitest";
import { LENS_ROUTES } from "../../../../testing/fixtures.js";
import FilterSheet from "./FilterSheet.js";

/** Render `ui` under the fixtures' router at `href`. */
const renderAt = (href: string, ui: ReactElement) => {
  const router = createRouter(LENS_ROUTES, {
    adapter: createMemoryAdapter(href),
  });
  return {
    router,
    ...render(<RouterProvider router={router}>{ui}</RouterProvider>),
  };
};

describe("FilterSheet", () => {
  it("is open when the address opens it", () => {
    renderAt(
      "/catalog?sheet=filter",
      <FilterSheet open>
        <p>Facets</p>
      </FilterSheet>,
    );
    const sheet = screen.getByRole("dialog", { name: "Filters" });
    expect(sheet).toHaveAttribute("open");
    expect(sheet.dataset.region).toBe("filter-sheet");
    expect(screen.getByText("Facets")).toBeInTheDocument();
  });

  it("is closed otherwise", () => {
    const { container } = renderAt(
      "/catalog",
      <FilterSheet open={false}>Facets</FilterSheet>,
    );
    expect(container.querySelector("dialog")).not.toHaveAttribute("open");
  });

  it("closes through a link to the address without the sheet", () => {
    renderAt(
      "/catalog?q=cen&sheet=filter",
      <FilterSheet open>Facets</FilterSheet>,
    );
    expect(screen.getByRole("link", { name: "Close" })).toHaveAttribute(
      "href",
      "/catalog?q=cen",
    );
  });

  it("closes on Escape by writing the address", () => {
    const { router } = renderAt(
      "/catalog?sheet=filter",
      <FilterSheet open>Facets</FilterSheet>,
    );
    const setSearchParams = vi.spyOn(router, "setSearchParams");
    fireEvent.keyDown(screen.getByRole("dialog"), { key: "Escape" });
    expect(setSearchParams).toHaveBeenCalledWith({ sheet: null });
  });

  it("leaves any other key, and a prevented Escape, to the caller", () => {
    const onKeyDown = vi.fn((event: { preventDefault: () => void }) => {
      event.preventDefault();
    });
    const { router } = renderAt(
      "/catalog?sheet=filter",
      <FilterSheet onKeyDown={onKeyDown} open>
        Facets
      </FilterSheet>,
    );
    const setSearchParams = vi.spyOn(router, "setSearchParams");
    fireEvent.keyDown(screen.getByRole("dialog"), { key: "Escape" });
    fireEvent.keyDown(screen.getByRole("dialog"), { key: "Enter" });
    expect(onKeyDown).toHaveBeenCalledTimes(2);
    expect(setSearchParams).not.toHaveBeenCalled();
  });

  it("moves focus to its title when it opens", () => {
    renderAt("/catalog?sheet=filter", <FilterSheet open>Facets</FilterSheet>);
    expect(screen.getByRole("heading", { name: "Filters" })).toHaveFocus();
  });

  it("applies custom className and passes native props through", () => {
    renderAt(
      "/catalog",
      <FilterSheet className="custom-class" data-testid="sheet" open={false}>
        Facets
      </FilterSheet>,
    );
    const sheet = screen.getByTestId("sheet");
    expect(sheet.className).toContain("ds filter-sheet");
    expect(sheet.className).toContain("custom-class");
  });
});
